import {RoomTransport} from './network-transport.js';
import {SIGNAL_URL} from './network-protocol.js';

export const partySecret=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
export function partyInvite(host,key){if(!/^[a-f0-9-]{36}$/.test(host)||!/^[a-f0-9]{32}$/.test(key))throw Error('Invalid lobby identity.');const hex=host.replaceAll('-','')+key;return 'BC2-'+btoa(String.fromCharCode(...hex.match(/../g).map(pair=>parseInt(pair,16)))).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');}
export function parsePartyInvite(value){try{const code=String(value).trim();if(!/^BC2-[a-zA-Z0-9_-]{43}$/.test(code))throw Error();const bytes=atob(code.slice(4).replaceAll('-','+').replaceAll('_','/'));if(bytes.length!==32)throw Error();const hex=Array.from(bytes,char=>char.charCodeAt(0).toString(16).padStart(2,'0')).join(''),id=hex.slice(0,32);return {host:id.slice(0,8)+'-'+id.slice(8,12)+'-'+id.slice(12,16)+'-'+id.slice(16,20)+'-'+id.slice(20),key:hex.slice(32),code};}catch{throw Error('Enter the complete BC2 lobby invite code.');}}

// One broker socket introduces a host-star of peers. Gameplay never passes
// through this socket. Existing peers survive a signaling-only interruption.
export class PartySignaler{
 constructor({onRegistered=()=>{},onRequest=()=>{},onResponse=()=>{},onError=()=>{},WebSocketClass=globalThis.WebSocket,RTCClass=globalThis.RTCPeerConnection}={}){Object.assign(this,{onRegistered,onRequest,onResponse,onError,WebSocketClass,RTCClass});this.routes=new Map();this.closed=false;this.connect();}
 connect(){if(this.closed)return;if(!this.WebSocketClass||!this.RTCClass){this.onError('This browser does not support WebRTC.');return;}let socket;try{socket=new this.WebSocketClass(SIGNAL_URL);}catch{this.retry();return;}this.socket=socket;this.registered=false;this.watchdog=setTimeout(()=>{if(!this.registered)socket.close();},12000);this.watchdog.unref?.();socket.onmessage=event=>{if(this.closed||this.socket!==socket)return;let message;try{message=JSON.parse(event.data);}catch{return;}if(message.kind==='registration-success'&&typeof message.clientID==='string'&&Array.isArray(message.iceServers)){this.id=message.clientID;this.iceServers=message.iceServers;this.registered=true;clearTimeout(this.watchdog);this.onRegistered(this.id);}else if(message.kind==='server-error'){if(!this.routes.size)this.onError('The lobby service rejected a signaling message. Reload and try again.');}else if(message.kind==='peer-message'){if(message.type==='offer'&&message.payload?.boostCircuit==='party-request')this.onRequest(message.sourceID,message.payload);else if(message.type==='answer'&&['party-accept','party-reject'].includes(message.payload?.boostCircuit))this.onResponse(message.sourceID,message.payload.boostCircuit,message.payload);else{const peer=this.routes.get(message.sourceID);if(peer)peer.signalChain=peer.signalChain.then(()=>peer.signal(JSON.stringify(message))).catch(()=>peer.fail('The peer connection could not be negotiated.'));}}};socket.onclose=()=>{clearTimeout(this.watchdog);if(!this.closed&&this.socket===socket)this.retry();};socket.onerror=()=>{};}
 retry(){if(this.closed)return;clearTimeout(this.retryTimer);this.retryTimer=setTimeout(()=>this.connect(),1000);this.retryTimer.unref?.();}
 send(peer,type,payload){if(this.closed||!this.registered||this.socket?.readyState!==1)return false;const application=type.startsWith('party-'),wireType=application?(type==='party-request'?'offer':'answer'):type,wirePayload=application?{...payload,boostCircuit:type}:payload;try{this.socket.send(JSON.stringify({kind:'send-message',destinationID:peer,type:wireType,payload:wirePayload}));return true;}catch{return false;}}
 peer(peerID,initiator,callbacks){const signaler=this;class DirectPeer extends RoomTransport{sendSignal(message){return signaler.send(message.destinationID,message.type,message.payload);}close(){if(signaler.routes.get(peerID)===this)signaler.routes.delete(peerID);super.close();}}
  const link=new DirectPeer({...callbacks,RTCClass:this.RTCClass,WebSocketClass:this.WebSocketClass});link.role=initiator?'guest':'host';link.iceServers=this.iceServers;link.ws={readyState:1,close(){}};this.routes.set(peerID,link);link.makePeer(peerID,initiator);if(initiator)Promise.resolve().then(()=>link.offer()).catch(()=>link.fail('The peer connection could not be negotiated.'));return link;
 }
 close(){if(this.closed)return;this.closed=true;clearTimeout(this.watchdog);clearTimeout(this.retryTimer);for(const link of [...this.routes.values()])link.close();this.routes.clear();if(this.socket){this.socket.onclose=null;this.socket.close();}}
}
